const UI = Object.fromEntries(UI_DEFS.map(d => [d[0], d[3]]));
const fill = (str, v) => v ? String(str).replace(/\{(\w+)\}/g, (m, k) => (k in v ? v[k] : m)) : String(str);
const tx = (key, v) => fill(UI[key] != null ? UI[key] : key, v);
// an item's text field, with its {placeholders} filled in
function itemText(item, field, w) { const f = field === 'desc' && item.pick ? item.pick(w) : field; return fill(item[f], item.vars ? item.vars(w) : null); }
// keys for an item's editable fields, for "Pick on screen"
const itemKeys = (prefix, it, fields) => fields.filter(f => typeof it[f] === 'string').map(f => prefix + '.' + (it.id || it.res) + '.' + f);

